def positions_for_existing_duties(apps, schema_editor):
    """Each existing duty gets one position "any qualification" with its number of helpers."""
    Duty = apps.get_model("duties", "Duty")
    DutyPosition = apps.get_model("duties", "DutyPosition")
    Report = apps.get_model("duties", "Report")
    for duty in Duty.objects.all().iterator():
        position = DutyPosition.objects.create(duty=duty, count=duty.helpers_needed)
        Report.objects.filter(duty=duty).update(position=position)


